package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ArrayBuilders;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.LRUMap;
import java.io.*;
import java.lang.reflect.*;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import java.util.Properties;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for TypeFactory.constructMapType(Class<? extends Map>, Class<?>, Class<?>)
 */
public class TypeFactory_constructMapType_TriageGen0Test {

    private TypeFactory typeFactory;

    @Before
    public void setUp() {
        typeFactory = TypeFactory.defaultInstance();
    }

    /**
     * Tests the branch where mapClass is Properties.class.
     * According to the logic, both key and value should be treated as String.
     */
    @Test
    public void testConstructMapType_WithPropertiesClass() {
        MapType result = typeFactory.constructMapType(Properties.class, Object.class, Object.class);

        Assert.assertNotNull("Resulting MapType should not be null", result);
        Assert.assertEquals("Map class should be Properties", Properties.class, result.rawClass());

        // In Properties, key and value are forced to String types by the implementation
        JavaType keyType = result.getKeyType();
        JavaType valueType = result.getValueType();

        Assert.assertEquals("Key type for Properties must be String", String.class, keyType.getRawClass());
        Assert.assertEquals("Value type for Properties must be String", String.class, valueType.getRawClass());
    }

    /**
     * Tests the branch where mapClass is NOT Properties.class.
     * This ensures that the provided keyClass and valueClass are correctly mapped.
     */
    @Test
    public void testConstructMapType_WithHashMapAndCustomTypes() {
        Class<? extends Map> mapClass = HashMap.class;
        Class<?> keyClass = Integer.class;
        Class<?> valueClass = Boolean.class;

        MapType result = typeFactory.constructMapType(mapClass, keyClass, valueClass);

        Assert.assertNotNull("Resulting MapType should not be null", result);
        Assert.assertEquals("Map class should be HashMap", HashMap.class, result.rawClass());
        Assert.assertEquals("Key type should be Integer", Integer.class, result.getKeyType().getRawClass());
        Assert.assertEquals("Value type should be Boolean", Boolean.class, result.getValueType().getRawClass());
    }

    /**
     * Tests the branch where mapClass is NOT Properties.class using different types.
     */
    @Test
    public void testConstructMapType_WithTreeMapAndStringTypes() {
        Class<? extends Map> mapClass = java.util.TreeMap.class;
        Class<?> keyClass = String.class;
        Class<?> valueClass = Double.class;

        MapType result = typeFactory.constructMapType(mapClass, keyClass, valueClass);

        Assert.assertNotNull("Resulting MapType should not be null", result);
        Assert.assertEquals("Map class should be TreeMap", java.util.TreeMap.class, result.rawClass());
        Assert.assertEquals("Key type should be String", String.class, result.getKeyType().getRawClass());
        Assert.assertEquals("Value type should be Double", Double.class, result.getValueType().getRawClass());
    }

    /**
     * Tests the branch where mapClass is NOT Properties.class using primitive wrappers.
     */
    @Test
    public void testConstructMapType_WithPrimitiveWrappers() {
        MapType result = typeFactory.constructMapType(HashMap.class, Long.class, Float.class);

        Assert.assertNotNull(result);
        Assert.assertEquals(Long.class, result.getKeyType().getRawClass());
        Assert.assertEquals(Float.class, result.getValueType().getRawClass());
    }
}
